inline const AIS *GetAIS(const void *buf) {
  return ::flatbuffers::GetRoot<AIS>(buf);
}

inline const AIS *GetSizePrefixedAIS(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<AIS>(buf);
}

inline const char *AISIdentifier() {
  return "$AIS";
}

inline bool AISBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, AISIdentifier());
}

inline bool SizePrefixedAISBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, AISIdentifier(), true);
}

template <bool B = false>
inline bool VerifyAISBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<AIS>(AISIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedAISBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<AIS>(AISIdentifier());
}

inline void FinishAISBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<AIS> root) {
  fbb.Finish(root, AISIdentifier());
}

inline void FinishSizePrefixedAISBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<AIS> root) {
  fbb.FinishSizePrefixed(root, AISIdentifier());
}

